916	        }
917	        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
918	        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
919	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
920	        }
921	        SortedMap<String, String> gradeTerms = new TreeMap<>();
922	        if (body != null && body.gradeTerms() != null) {
923	            for (Map.Entry<String, String> entry : body.gradeTerms().entrySet()) {
924	                String grade = entry.getKey() == null ? "" : entry.getKey().trim();
925	                String days = entry.getValue() == null ? "" : entry.getValue().trim();
926	                if (days.isEmpty()) {
